import boto3
import os
from flask import Flask, request, jsonify, g
from functools import wraps
import jwt

app = Flask(__name__)
DYNAMO_TABLE = os.environ.get('DYNAMO_TABLE', 'user_documents')
JWT_SECRET = os.environ.get('JWT_SECRET', 'changeme')

dynamodb = boto3.resource('dynamodb')
table = dynamodb.Table(DYNAMO_TABLE)

def authenticate(f):
    @wraps(f)
    def decorated(*args, **kwargs):
        token = request.headers.get('Authorization', '').replace('Bearer ', '')
        if not token:
            return jsonify({'error': 'Missing token'}), 401
        try:
            payload = jwt.decode(token, JWT_SECRET, algorithms=['HS256'])
            g.user_id = payload['sub']
            g.tenant_id = payload.get('tenant_id', 'default')
        except jwt.InvalidTokenError:
            return jsonify({'error': 'Invalid token'}), 401
        return f(*args, **kwargs)
    return decorated

@app.route('/api/documents/<document_id>', methods=['GET'])
@authenticate
def get_document(document_id):
    """Fetch a document by ID. The document_id is user-supplied."""
    # VULNERABILITY: No authorization check that document belongs to g.user_id
    # Any authenticated user can access any document by guessing/enumerating document_id
    response = table.get_item(
        Key={
            'tenant_id': g.tenant_id,
            'document_id': document_id
        }
    )
    item = response.get('Item')
    if not item:
        return jsonify({'error': 'Not found'}), 404
    return jsonify(item)

@app.route('/api/documents', methods=['POST'])
@authenticate
def create_document():
    """Create a new document for the authenticated user."""
    data = request.get_json()
    if not data or 'content' not in data:
        return jsonify({'error': 'Missing content'}), 400

    import uuid
    doc_id = str(uuid.uuid4())
    item = {
        'tenant_id': g.tenant_id,
        'document_id': doc_id,
        'owner_id': g.user_id,
        'content': data['content'],
        'classification': data.get('classification', 'internal')
    }
    table.put_item(Item=item)
    return jsonify({'document_id': doc_id}), 201

@app.route('/api/documents/<document_id>', methods=['DELETE'])
@authenticate
def delete_document(document_id):
    """Delete a document. No ownership check performed at application layer."""
    table.delete_item(
        Key={
            'tenant_id': g.tenant_id,
            'document_id': document_id
        }
    )
    return jsonify({'status': 'deleted'}), 200

@app.route('/api/users/<user_id>/documents', methods=['GET'])
@authenticate
def list_user_documents(user_id):
    """List documents for a specific user. Intended for admin use but no role check."""
    response = table.query(
        IndexName='owner-index',
        KeyConditionExpression=boto3.dynamodb.conditions.Key('owner_id').eq(user_id)
    )
    return jsonify(response.get('Items', []))

if __name__ == '__main__':
    app.run(host='0.0.0.0', port=8080)
